@interface TFAIAgentText : UIViewController
@property NSString *initial,*root,*expected;
@property BOOL memory;
@property UITextView *text;
@end
@implementation TFAIAgentText
- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=UIColor.systemBackgroundColor;self.text=[[UITextView alloc]initWithFrame:self.view.bounds];self.text.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;self.text.font=[UIFont monospacedSystemFontOfSize:14 weight:UIFontWeightRegular];self.text.textContainerInset=UIEdgeInsetsMake(16,12,16,12);self.text.text=self.initial;self.text.editable=self.memory;[self.view addSubview:self.text];if(self.memory)self.navigationItem.rightBarButtonItem=AIBar(@"checkmark",@"保存",self,@selector(save));}
- (void)save{TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease tryWrite];if(!lease){AIAlert(self,@"项目正在处理",@"请等待当前文件或Git操作完成后保存。");return;}NSError *error=nil;if(![TFAIAgentContext saveMemory:self.text.text root:self.root expected:self.expected error:&error]){AIAlert(self,@"记忆未保存",error.localizedDescription);return;}self.expected=[TFAIAgentContext fingerprint:self.text.text];[self.navigationController popViewControllerAnimated:YES];}
@end
@interface TFAIMCPToolsPage : UITableViewController
@property NSDictionary *server;
@property NSString *sessionID,*sessionTitle;
@property NSArray *tools;
@property BOOL busy;
@end
@implementation TFAIMCPToolsPage
- (void)viewDidLoad{[super viewDidLoad];self.title=self.server[@"name"];self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=70;self.navigationItem.rightBarButtonItems=@[AIBar(@"arrow.clockwise",@"发现工具",self,@selector(discover)),AIBar(@"wrench.and.screwdriver",@"配置与诊断",self,@selector(configuration))];if(![self.server[@"transport"] isEqual:@"stdio"])[self discover];}

- (void)configuration{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"配置与诊断" message:@"不会显示环境密钥或服务器原始 stderr。" preferredStyle:UIAlertControllerStyleActionSheet];[a addAction:[UIAlertAction actionWithTitle:@"检查依赖与连接状态" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[self diagnose];}]];if([self.server[@"transport"] isEqual:@"stdio"]){[a addAction:[UIAlertAction actionWithTitle:@"设置环境变量 / 密钥" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){TFAIFieldSheet *p=[TFAIFieldSheet new];p.title=@"环境变量（钥匙串）";p.secure=YES;p.hint=@"输入完整 JSON 字典替换环境配置，如 {\"SERVICE_TOKEN\":\"你的值\"}。值只保存钥匙串，不写入配置文件、日志或工具历史。{} 清空。修改后须重新启动并授权工具。";p.value=@"{}";p.save=^(NSString *value){NSError *e=nil;id env=[NSJSONSerialization JSONObjectWithData:[value dataUsingEncoding:NSUTF8StringEncoding] options:0 error:&e];if(!e&&[TFAIMCP.shared setEnvironment:env server:self.server[@"id"] error:&e]){self.tools=@[];[self.tableView reloadData];}else AIAlert(self,@"环境配置未保存",e.localizedDescription?:@"请输入 JSON 字典");};[self presentViewController:[[TMCNavigationController alloc]initWithRootViewController:p] animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"安装 Python / Node 等官方依赖" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIAlertController *confirm=[UIAlertController alertControllerWithTitle:@"安装到本会话 Linux？" message:@"安装 App 随附的 Alpine 官方签名工具包，不启动服务器。完成后可重新检查依赖；服务专用 npm/pip 包仍须在 Linux 终端明确安装。" preferredStyle:UIAlertControllerStyleAlert];[confirm addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[confirm addAction:[UIAlertAction actionWithTitle:@"确认安装" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[TFAIISHRuntime.shared installDeveloperTools:self.sessionID completion:^(NSDictionary *r,NSError *e){if(e)AIAlert(self,@"安装未启动",e.localizedDescription);else{[self.navigationController pushViewController:TFAIISHTerminalController(self.sessionID) animated:YES];AIAlert(self.navigationController.topViewController,@"安装任务已启动",[NSString stringWithFormat:@"任务 %@；终端的后台进程菜单可查看安装进度。安装完成后回到服务页检查依赖。",r[@"process_id"]]);}}];}]];[self presentViewController:confirm animated:YES completion:nil];}]];}[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:a animated:YES completion:nil];}
- (void)diagnose{NSDictionary *d=[TFAIMCP.shared diagnostics:self.server[@"id"] session:self.sessionID];NSString *base=[NSString stringWithFormat:@"传输：%@\n进程：%@\n会话启用：%@\n已发现 / 已授权：%@ / %@\n环境变量名：%@",d[@"transport"],d[@"state"],[d[@"sessionEnabled"] boolValue]?@"是":@"否",d[@"discoveredTools"],d[@"allowedTools"],[d[@"environmentKeys"] componentsJoinedByString:@", "]];if(![self.server[@"transport"] isEqual:@"stdio"]){AIAlert(self,@"MCP 诊断",[base stringByAppendingString:@"\nHTTP 请使用发现工具验证真实请求；配置存在不代表连接成功。"]);return;}NSMutableArray *lines=[NSMutableArray new];NSArray *commands=@[self.server[@"command"]?:@"/missing",@"/usr/bin/python3",@"/usr/bin/node",@"/usr/bin/npm"];__block NSUInteger at=0;__block void(^next)(void);next=^{if(at==commands.count){AIAlert(self,@"MCP 诊断",[base stringByAppendingFormat:@"\n\n%@",[lines componentsJoinedByString:@"\n"]]);next=nil;return;}NSString *command=commands[at++];[TFAIISHRuntime.shared fileOperation:@"probe" path:command arguments:@{} session:self.sessionID completion:^(NSDictionary *r,NSError *e){[lines addObject:[NSString stringWithFormat:@"%@：%@",command,e?@"沙盒不可用":[r[@"executable"] boolValue]?@"可执行":@"未安装或不可执行"]];next();}];};next();}

- (void)discover{if(self.busy)return;BOOL local=[self.server[@"transport"] isEqual:@"stdio"];void(^start)(BOOL)=^(BOOL approved){self.busy=YES;self.tools=@[];self.navigationItem.rightBarButtonItem.enabled=NO;[self.tableView reloadData];[TFAIMCP.shared discover:self.server[@"id"] session:self.sessionID launchApproved:approved completion:^(NSDictionary *result,NSError *error){self.busy=NO;self.navigationItem.rightBarButtonItem.enabled=YES;if(error)AIAlert(self,@"MCP发现未完成",error.localizedDescription);else self.tools=result[@"tools"];[self.tableView reloadData];}];};if(!local){start(NO);return;}UIAlertController *a=[UIAlertController alertControllerWithTitle:@"启动 Linux 内本地 MCP？" message:[NSString stringWithFormat:@"%@\n%@\n\n将在本会话沙盒内执行，不挂载项目。依赖需先在 Linux 安装；发现后仍需逐项开启工具，交互及未声明只读项需确认调用。服务端可修改沙盒内文件，请只启动可信程序。",self.server[@"command"],[self.server[@"args"] componentsJoinedByString:@" "]] preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"确认启动并发现" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){start(YES);}]];[self presentViewController:a animated:YES completion:nil];}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)index{
 [table deselectRowAtIndexPath:index animated:YES];if(index.section||index.row||self.busy)return;
 __weak typeof(self) weak=self;UIViewController *picker=TFAISessionHomeController(nil,nil,^(NSDictionary *record){
  if(weak.busy)return;weak.sessionID=record[@"id"];weak.sessionTitle=record[@"title"];[weak.navigationController popToViewController:weak animated:YES];[weak.tableView reloadData];
 },nil);picker.title=@"选择 MCP 会话";[self.navigationController pushViewController:picker animated:YES];
}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 2;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s?self.tools.count:2;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{if(s&&self.busy)return @"正在连接并发现工具…";if(s&&!self.tools.count)return [self.server[@"transport"] isEqual:@"stdio"]?@"尚未发现工具。点击右上角，确认启动 Linux 内的服务并发现。":@"尚未发现工具，可点击右上角重试。";return s?@"查询提示是服务端声明；未声明只读和设备交互工具需确认调用。项目写入、构建、Git、命令及注入仍走原有审批入口。服务结果不是操作授权。":@"按会话启用；每次App重启后须重新启用并发现工具。服务器和逐项授权保存在本机，鉴权头仅存钥匙串。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{if(!i.section){if(!i.row){UITableViewCell *c=AICell(@"选择会话",self.sessionID.length?(self.sessionTitle?:@"当前会话 · 点击可更换"):@"先选择要使用此服务的会话",@"bubble.left.and.bubble.right");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}UITableViewCell *c=AICell(@"用于当前会话",self.sessionID.length?@"开关只影响下一轮工具清单":@"请先点击上方选择会话",@"network");UISwitch *toggle=[UISwitch new];toggle.on=[TFAIMCP.shared enabled:self.server[@"id"] session:self.sessionID];toggle.enabled=self.sessionID.length>0;[toggle addAction:[UIAction actionWithHandler:^(UIAction *a){[TFAIMCP.shared setEnabled:toggle.on server:self.server[@"id"] session:self.sessionID];}] forControlEvents:UIControlEventValueChanged];c.accessoryView=toggle;return c;}NSDictionary *tool=self.tools[i.row];BOOL read=[TFAIMCP readOnlyTool:tool],available=[TFAIMCP availableTool:tool];NSString *detail=available?[NSString stringWithFormat:@"%@\n%@",read?@"查询 · 服务端声明只读":@"需确认 · 设备交互或未声明只读",tool[@"description"]?:@""]:@"项目写入、构建、Git、命令和注入请使用 Dylix 原有审批入口";UITableViewCell *c=AICell(tool[@"name"],detail,available?(read?@"doc.text.magnifyingglass":@"hand.raised"):@"lock");UISwitch *toggle=[UISwitch new];toggle.enabled=available;NSDictionary *current=nil;for(NSDictionary *server in TFAIMCP.shared.servers)if([server[@"id"] isEqual:self.server[@"id"]])current=server;toggle.on=[current[@"allowedTools"] containsObject:tool[@"name"]];[toggle addAction:[UIAction actionWithHandler:^(UIAction *a){NSError *error=nil;void(^save)(void)=^{NSError *error=nil;if(![TFAIMCP.shared setAllowed:toggle.on tool:tool[@"name"] server:self.server[@"id"] error:&error]){toggle.on=NO;AIAlert(self,@"工具未开启",error.localizedDescription);}};if(toggle.on&&!read){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"允许 AI 使用此 MCP 工具？" message:@"它可能改变设备状态，或没有声明只读。调用仍需按当前会话权限确认；请只启用你信任的服务。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:^(id x){toggle.on=NO;}]];[a addAction:[UIAlertAction actionWithTitle:@"允许使用" style:UIAlertActionStyleDefault handler:^(id x){save();}]];[self presentViewController:a animated:YES completion:nil];}else save();}] forControlEvents:UIControlEventValueChanged];c.accessoryView=toggle;return c;}
@end
@interface TFAIMCPPage : UITableViewController
@property NSString *sessionID;
@property NSArray *servers;
@end
@implementation TFAIMCPPage
- (void)viewDidLoad{[super viewDidLoad];self.title=@"MCP 服务";self.navigationItem.rightBarButtonItem=AIBar(@"plus",@"添加 MCP",self,@selector(addServer));self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=70;}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.servers=TFAIMCP.shared.servers;[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.servers.count;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return @"支持 Streamable HTTP 和 Linux 沙盒内 STDIO。导入默认关闭，本地启动需确认；逐项审核工具并按会话开启。关闭会话开关会停止本地 MCP。HTTP 局域网传输为明文。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *s=self.servers[i.row];UITableViewCell *c=AICell(s[@"name"],s[@"url"]?:[NSString stringWithFormat:@"Linux STDIO · %@",s[@"command"]],@"network");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{TFAIMCPToolsPage *p=[[TFAIMCPToolsPage alloc]initWithStyle:UITableViewStyleInsetGrouped];p.server=self.servers[i.row];p.sessionID=self.sessionID;[self.navigationController pushViewController:p animated:YES];}
- (void)tableView:(UITableView *)t commitEditingStyle:(UITableViewCellEditingStyle)style forRowAtIndexPath:(NSIndexPath *)i{if(style==UITableViewCellEditingStyleDelete){NSDictionary *server=self.servers[i.row];UIAlertController *a=[UIAlertController alertControllerWithTitle:@"删除服务器与本机鉴权头？" message:server[@"name"] preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"删除" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[TFAIMCP.shared remove:server[@"id"]];self.servers=TFAIMCP.shared.servers;[t reloadData];}]];[self presentViewController:a animated:YES completion:nil];}}

- (void)addServer{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"添加 MCP 服务" message:@"导入只保存配置，不执行安装或启动。" preferredStyle:UIAlertControllerStyleActionSheet];[a addAction:[UIAlertAction actionWithTitle:@"导入 mcpServers JSON" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[self import];}]];[a addAction:[UIAlertAction actionWithTitle:@"本地 STDIO 设置向导" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){TFAIFieldSheet *p=[TFAIFieldSheet new];p.title=@"本地 MCP 向导";p.secure=YES;p.hint=@"1. 填名称、Linux 绝对 command 和 args 数组。2. 保存后进入配置与诊断，检查并安装 Python/Node 依赖。3. 在 Linux 安装可信服务包。4. 配置环境密钥，确认启动并发现。5. 逐项启用工具，再打开本会话开关。不会自动下载或运行第三方脚本。";p.value=@"{\"mcpServers\":{\"本地服务\":{\"transport\":\"stdio\",\"command\":\"/usr/bin/python3\",\"args\":[]}}}";p.save=^(NSString *value){NSError *e=nil;if(![TFAIMCP.shared importJSON:value error:&e])AIAlert(self,@"未保存",e.localizedDescription);else{self.servers=TFAIMCP.shared.servers;[self.tableView reloadData];}};[self presentViewController:[[TMCNavigationController alloc]initWithRootViewController:p] animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItem;[self presentViewController:a animated:YES completion:nil];}

- (void)import{TFAIFieldSheet *page=[TFAIFieldSheet new];page.title=@"导入 MCP";page.hint=@"粘贴 mcpServers JSON。HTTP 使用 url/headers；本地使用 transport:stdio、command（Linux 绝对路径）、args（数组）。env 字典的值只存钥匙串；不要将密钥放进 args。启动前需确认。";page.value=@"{\"mcpServers\":{\"名称\":{\"url\":\"\"}}}";page.secure=YES;page.save=^(NSString *value){NSError *error=nil;if(![TFAIMCP.shared importJSON:value error:&error])AIAlert(self,@"导入未完成",error.localizedDescription);else{self.servers=TFAIMCP.shared.servers;[self.tableView reloadData];}};[self presentViewController:[[TMCNavigationController alloc]initWithRootViewController:page] animated:YES completion:nil];}
@end
@interface TFAIAgentSettings : UITableViewController
@property NSString *root,*sessionID;
@property NSArray *skills;
@property(copy) void (^onBrowserAsk)(NSString *url);
@end
@implementation TFAIAgentSettings
- (void)viewDidLoad{[super viewDidLoad];self.title=@"Agent 能力";self.navigationItem.rightBarButtonItem=AIBar(@"switch.2",@"功能开关",self,@selector(toolSettings));self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=70;}
- (void)toolSettings{[self.navigationController pushViewController:TFAIToolRegistrySettingsController() animated:YES];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.skills=[TFAIAgentContext skills:self.root];[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 3;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?self.skills.count+(self.root.length?1:0):(s==2?3:2);}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return @[@"技能",@"记忆与构建",@"连接与浏览"][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return s==0?@"技能正文只在 AI 需要时读取；项目中已有技能不会被覆盖。":s==1?@"记忆保存在本机。关联项目时使用项目 MEMORY.md；未关联时使用通用记忆。":@"浏览器显示真实网页，可将当前页交给 AI；MCP 仅调用你启用的工具，交互及未声明只读项需确认。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSString *title,*detail,*icon;if(i.section==2&&i.row==2){UITableViewCell *cell=AICell(@"Linux 终端",[TFAIISHRuntime available]?@"Alpine · 当前会话文件与 AI 命令共用":@"当前构建未携带 ARM64 iSH 运行库",@"terminal");cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;}if(i.section==0){if(i.row==self.skills.count){title=@"安装技能到当前项目";detail=@"保留已有文件";icon=@"plus.square.on.square";}else{NSDictionary *s=self.skills[i.row];title=s[@"name"];detail=[NSString stringWithFormat:@"%@ · %@",[s[@"source"] isEqual:@"builtin"]?@"内置":@"项目",s[@"description"]];icon=@"text.book.closed";}}else if(i.section==1){title=i.row?@"构建任务":self.root.length?@"项目记忆":@"通用记忆";detail=i.row?@"查看队列和进度":@"编辑 AI 按需读取的本机笔记";icon=i.row?@"hammer":@"brain";}else{title=i.row?@"浏览器":@"MCP 服务";detail=i.row?@"浏览网页，并将当前页交给 AI":@"管理服务、工具授权与会话开关";icon=i.row?@"globe":@"network";}UITableViewCell *c=AICell(title,detail,icon);c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(i.section==2&&i.row==2){[self.navigationController pushViewController:TFAIISHTerminalControllerWithRoot(self.sessionID,self.root) animated:YES];return;}if(i.section==0){if(i.row==self.skills.count){TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease tryWrite];if(!lease){AIAlert(self,@"项目正在处理",@"请稍后安装技能。");return;}NSError *error=nil;if(![TFAIAgentContext installSkills:self.root error:&error])AIAlert(self,@"技能安装未完成",error.localizedDescription);self.skills=[TFAIAgentContext skills:self.root];[t reloadData];return;}NSError *error=nil;NSDictionary *r=[TFAIAgentContext readSkill:self.skills[i.row][@"id"] root:self.root error:&error];if(error){AIAlert(self,@"技能读取失败",error.localizedDescription);return;}TFAIAgentText *page=[TFAIAgentText new];page.title=self.skills[i.row][@"name"];page.initial=r[@"body"];[self.navigationController pushViewController:page animated:YES];return;}if(i.section==1){if(i.row){[self.navigationController pushViewController:TFAIBuildQueueController() animated:YES];return;}NSError *error=nil;NSString *text=[TFAIAgentContext memory:self.root error:&error];if(!text){AIAlert(self,@"记忆读取失败",error.localizedDescription);return;}TFAIAgentText *page=[TFAIAgentText new];page.title=self.root.length?@"项目记忆":@"通用记忆";page.root=self.root;page.memory=YES;page.initial=text;page.expected=[TFAIAgentContext fingerprint:text];[self.navigationController pushViewController:page animated:YES];return;}if(i.row)[self.navigationController pushViewController:TFAIReadOnlyBrowserControllerWithAsk(self.sessionID,self.onBrowserAsk) animated:YES];else{TFAIMCPPage *p=[[TFAIMCPPage alloc]initWithStyle:UITableViewStyleInsetGrouped];p.sessionID=self.sessionID;[self.navigationController pushViewController:p animated:YES];}}
@end
UIViewController *TFAIAgentSettingsControllerWithBrowserAction(NSString *root,NSString *session,void (^onAsk)(NSString *url)){TFAIAgentSettings *p=[[TFAIAgentSettings alloc]initWithStyle:UITableViewStyleInsetGrouped];p.root=root;p.sessionID=session;p.onBrowserAsk=onAsk;return p;}
UIViewController *TFAIAgentSettingsController(NSString *root,NSString *session){return TFAIAgentSettingsControllerWithBrowserAction(root,session,nil);}
